def get_parent_robust(p_idx):
    p_coords = coords_by_person[p_idx]
    p_coords_set = set(p_coords)

    # We find starting points above the child box.
    # Instead of just the row min_r - 1, we search in a window from min_r - 1 to min_r - 4
    # and column range min_c - 4 to max_c + 4.
