import csv
import json
import os
from collections import deque

def answer() -> int:
    # File paths
    csv_path = "/app/dataset/people_accounts.csv"
    tree_path = "/app/dataset/genealogy_trees.txt"

    # 1. Read accounts and balances
    people_list = []
    balances = {}
    with open(csv_path, encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
            name = f"{row['first_name']} {row['last_name']}"
            people_list.append((row['first_name'], row['last_name']))
            balances[name] = int(row['account_balance'])

    # 2. Read and pad genealogy tree diagram
    with open(tree_path, encoding='utf-8') as f:
        tree_lines = [line.rstrip('\r\n') for line in f.readlines()]
    H = len(tree_lines)
    W = max(len(line) for line in tree_lines)
    tree_lines = [line.ljust(W) for line in tree_lines]

    # 3. Find exact coordinate cells of names in the tree
    person_by_coord = {}
    coords_by_person = []
    person_names = []

    def find_name_coords(fn, ln):
        full_name = f"{fn} {ln}"
        # Case A: Same line match
        for r, line in enumerate(tree_lines):
            if full_name in line:
                c = line.index(full_name)
                return [(r, col) for col in range(c, c + len(full_name))]
        # Case B: Multi-line match (vertically aligned)
        for r in range(H - 1):
            if fn in tree_lines[r] and ln in tree_lines[r+1]:
                c1 = tree_lines[r].index(fn)
                c2 = tree_lines[r+1].index(ln)
                if abs(c1 - c2) < 20:
                    return ([(r, col) for col in range(c1, c1 + len(fn))] +
                            [(r+1, col) for col in range(c2, c2 + len(ln))])
            if ln in tree_lines[r] and fn in tree_lines[r+1]:
                c1 = tree_lines[r].index(ln)
                c2 = tree_lines[r+1].index(fn)
                if abs(c1 - c2) < 20:
                    return ([(r, col) for col in range(c1, c1 + len(ln))] +
                            [(r+1, col) for col in range(c2, c2 + len(fn))])
        return []

    for i, (fn, ln) in enumerate(people_list):
        c_list = find_name_coords(fn, ln)
        if c_list:
            p_idx = len(coords_by_person)
            coords_by_person.append(c_list)
            person_names.append(f"{fn} {ln}")
            for r, c in c_list:
                person_by_coord[(r, c)] = p_idx

    # 4. BFS function to trace parents upwards
    def get_parent_all_rows(p_idx):
        p_coords = coords_by_person[p_idx]
        p_coords_set = set(p_coords)

        min_r = min(r for r, c in p_coords)
        cols = [c for r, c in p_coords if r == min_r]
        min_c, max_c = min(cols), max(cols)

        # Scan 5 rows above the top row of the person's name for starting connector nodes
        start_nodes = []
        for r in range(min_r - 1, max(-1, min_r - 6), -1):
            for c in range(max(0, min_c - 4), min(W, max_c + 5)):
                char = tree_lines[r][c]
                if char != ' ' and (r, c) not in p_coords_set:
                    if char in '|│+-_~\\/':
                        start_nodes.append((r, c))

        if not start_nodes:
            return None

        queue = deque(start_nodes)
        visited = set(start_nodes)

        while queue:
            r, c = queue.popleft()
            if (r, c) in person_by_coord:
                other_p = person_by_coord[(r, c)]
                if other_p != p_idx:
                    return person_names[other_p]

            # Follow line connectors: dr <= 0 enforces tracing upwards or horizontally
            for step in [1, 2, 3]:
                found_moves = False
                for dr in range(-step, 1):  # dr <= 0
                    for dc in range(-step, step+1):
                        if dr == 0 and dc == 0:
                            continue
                        if abs(dr) > 1 and abs(dc) > 1:
                            continue

                        nr, nc = r + dr, c + dc
                        if 0 <= nr < H and 0 <= nc < W:
                            if (nr, nc) not in visited and (nr, nc) not in p_coords_set:
                                char = tree_lines[nr][nc]
                                if char != ' ':
                                    visited.add((nr, nc))
                                    queue.append((nr, nc))
                                    found_moves = True
                if found_moves:
                    break
        return None

    # 5. Build parents and children maps
    parent_of = {}
    children_of = {name: [] for name in person_names}

    for i, name in enumerate(person_names):
        parent = get_parent_all_rows(i)
        if parent:
            parent_of[name] = parent
            if parent not in children_of:
                children_of[parent] = []
            children_of[parent].append(name)

    # 6. Trace ancestors of Dawid Majtyka to find the great-great-grandparent
    ancestors = ['Dawid Majtyka']
    curr = 'Dawid Majtyka'
    while curr in parent_of:
        curr = parent_of[curr]
        ancestors.append(curr)

    if len(ancestors) < 5:
        raise ValueError("Dawid Majtyka's lineage is too short to find a great-great-grandparent!")

    gggp = ancestors[4] # great-great-grandparent

    # 7. Collect direct children and trace grandchildren
    direct_children = children_of.get(gggp, [])
    total_sum = 0
    for child in direct_children:
        grandchildren = []
        childs_children = children_of.get(child, [])
        for cc in childs_children:
            grandchildren.extend(children_of.get(cc, []))

        num_grandchildren = len(grandchildren)
        if num_grandchildren > 1:
            total_sum += balances.get(child, 0)

    return total_sum

if __name__ == "__main__":
    ans = answer()
    print(f"Calculated Answer: {ans}")
    with open("/app/answer.json", "w") as f:
        json.dump(ans, f, default=list)

