    # 5. Build parents and children maps
    parent_of = {}
    children_of = {name: [] for name in person_names}

    for i, name in enumerate(person_names):
        parent = get_parent_all_rows(i)
        if parent:
            parent_of[name] = parent
            if parent not in children_of:
                children_of[parent] = []
            children_of[parent].append(name)

    # 6. Trace ancestors of Dawid Majtyka to find the great-great-grandparent
    ancestors = ['Dawid Majtyka']
    curr = 'Dawid Majtyka'
    while curr in parent_of:
        curr = parent_of[curr]
        ancestors.append(curr)

    if len(ancestors) < 5:
        raise ValueError("Dawid Majtyka's lineage is too short to find a great-great-grandparent!")

    gggp = ancestors[4] # great-great-grandparent

    # 7. Collect direct children and trace grandchildren
    direct_children = children_of.get(gggp, [])
    total_sum = 0
    for child in direct_children:
        grandchildren = []
        childs_children = children_of.get(child, [])
        for cc in childs_children:
            grandchildren.extend(children_of.get(cc, []))

        num_grandchildren = len(grandchildren)
        if num_grandchildren > 1:
            total_sum += balances.get(child, 0)

    return total_sum

